import fs from "fs";
import { readGlb, getItem, u32, u16 } from "./glb.mjs";

const buf0 = fs.readFileSync("../data/FILE0000.GLB");
const buf1 = fs.readFileSync("../data/FILE0001.GLB");
const glb0 = readGlb(buf0);
const glb1 = readGlb(buf1);

const names1 = [...glb1.items.keys()];

function picInfo(glb, name) {
  const raw = getItem(glb, name);
  if (!raw) return "MISSING";
  const type = u32(raw, 0);
  const opt1 = i32raw(raw, 4);
  const opt2 = i32raw(raw, 8);
  const w = i32raw(raw, 12);
  const h = i32raw(raw, 16);
  return `type=${type} opt1=${opt1} opt2=${opt2} w=${w} h=${h} size=${raw.length}`;
}
function i32raw(u8, o) {
  const v = u8[o] | (u8[o + 1] << 8) | (u8[o + 2] << 16) | (u8[o + 3] << 24);
  return v;
}

// tiles between STARTG1TILES and ENDG1TILES
const startIdx = names1.indexOf("STARTG1TILES");
const endIdx = names1.indexOf("ENDG1TILES");
console.log("tile range idx", startIdx, endIdx, "count", endIdx - startIdx - 1);
console.log("first tile:", names1[startIdx + 1], picInfo(glb1, names1[startIdx + 1]));
console.log("last tile:", names1[endIdx - 1], picInfo(glb1, names1[endIdx - 1]));

// palette
const pal = getItem(glb1, "PALETTE_DAT");
console.log("palette size:", pal.length);
console.log("pal[0..5]:", [...pal.subarray(0, 6)]);

// player ship light pics
for (let i = 0; i < 7; i++) {
  const name = names1[0x11a + i];
